use builtin::*;
use vstd::prelude::*;

/// Computes two matrices (grid_x, grid_y) by “broadcasting” the
/// vectors `x` and `y`.
///
/// * grid_x has `y.len()` rows each equal to `x`.
/// * grid_y has `y.len()` rows each equal to `vec![ y[i] ; x.len() ]`.
#[verifier::verus]
#[spec]
#[verifier::throws(false)]
#[requires(true)]
#[ensures({
    // The number of rows of grid_x equals the length of y
    result.0.len() == y.len()
})]
#[ensures({
    // Each row of grid_x equals exactly x
    forall(|i: usize| i < y.len() ==>
        result.0[i] == x
    )
})]
#[ensures({
    // The number of rows of grid_y equals the length of y
    result.1.len() == y.len()
})]
#[ensures({
    // Each entry of grid_y at (i,j) is y[i]
    forall(|i: usize, j: usize| i < y.len() && j < x.len() ==>
        result.1[i][j] == y[i]
    )
})]
fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let cols = x.len();
    let rows = y.len();

    // Prepare the output matrices with the correct capacities.
    let mut grid_x = Vec::with_capacity(rows);
    let mut grid_y = Vec::with_capacity(rows);

    // Invariant: at each iteration we've pushed exactly `k` rows so far,
    //            so grid_x.len() == grid_y.len() == k,
    //            and that is ≤ rows.
    // Decreases ensures termination: rows − grid_x.len() strictly decreases.
    #[invariant(grid_x.len() == grid_y.len())]
    #[invariant(grid_x.len() <= rows)]
    #[decreases(rows - grid_x.len())]
    for &y_val in &y {
        // In grid_x, each row is just a clone of the entire x vector.
        grid_x.push(x.clone());

        // In grid_y, each row is a vector filled with the current y_val.
        grid_y.push(vec![y_val; cols]);
    }

    (grid_x, grid_y)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_meshgrid_basic() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![4.0, 5.0];
        let (gx, gy) = meshgrid(x, y);

        // grid_x should be
        // [[1.0, 2.0, 3.0],
        //  [1.0, 2.0, 3.0]]
        assert_eq!(gx.len(), 2);
        assert_eq!(gx[0], vec![1.0, 2.0, 3.0]);
        assert_eq!(gx[1], vec![1.0, 2.0, 3.0]);

        // grid_y should be
        // [[4.0, 4.0, 4.0],
        //  [5.0, 5.0, 5.0]]
        assert_eq!(gy.len(), 2);
        assert_eq!(gy[0], vec![4.0, 4.0, 4.0]);
        assert_eq!(gy[1], vec![5.0, 5.0, 5.0]);
    }
}